void traash_window_set_icon(GLFWwindow *window) {
  if (!window) {
    return;
  }
  GLFWimage images[6];
  images[0].width = 16;
  images[0].height = 16;
  images[0].pixels = (unsigned char *)traash_icon_16_rgba;
  images[1].width = 32;
  images[1].height = 32;
  images[1].pixels = (unsigned char *)traash_icon_32_rgba;
  images[2].width = 48;
  images[2].height = 48;
  images[2].pixels = (unsigned char *)traash_icon_48_rgba;
  images[3].width = 64;
  images[3].height = 64;
  images[3].pixels = (unsigned char *)traash_icon_64_rgba;
  images[4].width = 128;
  images[4].height = 128;
  images[4].pixels = (unsigned char *)traash_icon_128_rgba;
  images[5].width = 256;
  images[5].height = 256;
  images[5].pixels = (unsigned char *)traash_icon_256_rgba;
  glfwSetWindowIcon(window, 6, images);
}
